use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < T , C : cfg :: Config > Slab < T , C > { # [doc = " The number of bits in each index which are used by the slab."] # [doc = ""] # [doc = " If other data is packed into the `usize` indices returned by"] # [doc = " [`Slab::insert`], user code is free to use any bits higher than the"] # [doc = " `USED_BITS`-th bit freely."] # [doc = ""] # [doc = " This is determined by the [`Config`] type that configures the slab's"] # [doc = " parameters. By default, all bits are used; this can be changed by"] # [doc = " overriding the [`Config::RESERVED_BITS`][res] constant."] # [doc = ""] # [doc = " [res]: crate::Config#RESERVED_BITS"] pub const USED_BITS : usize = C :: USED_BITS ; # [doc = " Inserts a value into the slab, returning the integer index at which that"] # [doc = " value was inserted. This index can then be used to access the entry."] # [doc = ""] # [doc = " If this function returns `None`, then the shard for the current thread"] # [doc = " is full and no items can be added until some are removed, or the maximum"] # [doc = " number of shards has been reached."] # [doc = ""] # [doc = " # Examples"] # [doc = " ```rust"] # [doc = " # use sharded_slab::Slab;"] # [doc = " let slab = Slab::new();"] # [doc = ""] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = " assert_eq!(slab.get(key).unwrap(), \"hello world\");"] # [doc = " ```"] pub fn insert (& self , value : T) -> Option < usize > { let (tid , shard) = self . shards . current () ; test_println ! ("insert {:?}" , tid) ; let mut value = Some (value) ; shard . init_with (| idx , slot | { let gen = slot . insert (& mut value) ? ; Some (gen . pack (idx)) }) . map (| idx | tid . pack (idx)) } # [doc = " Return a handle to a vacant entry allowing for further manipulation."] # [doc = ""] # [doc = " This function is useful when creating values that must contain their"] # [doc = " slab index. The returned [`VacantEntry`] reserves a slot in the slab and"] # [doc = " is able to return the index of the entry."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let hello = {"] # [doc = "     let entry = slab.vacant_entry().unwrap();"] # [doc = "     let key = entry.key();"] # [doc = ""] # [doc = "     entry.insert((key, \"hello\"));"] # [doc = "     key"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(hello, slab.get(hello).unwrap().0);"] # [doc = " assert_eq!(\"hello\", slab.get(hello).unwrap().1);"] # [doc = " ```"] pub fn vacant_entry (& self) -> Option < VacantEntry < '_ , T , C > > { let (tid , shard) = self . shards . current () ; test_println ! ("vacant_entry {:?}" , tid) ; shard . init_with (| idx , slot | { let inner = slot . init () ? ; let key = inner . generation () . pack (tid . pack (idx)) ; Some (VacantEntry { inner , key , _lt : PhantomData , }) }) } # [doc = " Remove the value at the given index in the slab, returning `true` if a"] # [doc = " value was removed."] # [doc = ""] # [doc = " Unlike [`take`], this method does _not_ block the current thread until"] # [doc = " the value can be removed. Instead, if another thread is currently"] # [doc = " accessing that value, this marks it to be removed by that thread when it"] # [doc = " finishes accessing the value."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " let slab = sharded_slab::Slab::new();"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Remove the item from the slab."] # [doc = " assert!(slab.remove(key));"] # [doc = ""] # [doc = " // Now, the slot is empty."] # [doc = " assert!(!slab.contains(key));"] # [doc = " ```"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " let slab = Arc::new(sharded_slab::Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " let slab2 = slab.clone();"] # [doc = " let thread2 = std::thread::spawn(move || {"] # [doc = "     // Depending on when this thread begins executing, the item may"] # [doc = "     // or may not have already been removed..."] # [doc = "     if let Some(item) = slab2.get(key) {"] # [doc = "         assert_eq!(item, \"hello world\");"] # [doc = "     }"] # [doc = " });"] # [doc = ""] # [doc = " // The item will be removed by thread2 when it finishes accessing it."] # [doc = " assert!(slab.remove(key));"] # [doc = ""] # [doc = " thread2.join().unwrap();"] # [doc = " assert!(!slab.contains(key));"] # [doc = " ```"] # [doc = " [`take`]: Slab::take"] pub fn remove (& self , idx : usize) -> bool { let tid = C :: unpack_tid (idx) ; test_println ! ("rm_deferred {:?}" , tid) ; let shard = self . shards . get (tid . as_usize ()) ; if tid . is_current () { shard . map (| shard | shard . remove_local (idx)) . unwrap_or (false) } else { shard . map (| shard | shard . remove_remote (idx)) . unwrap_or (false) } } # [doc = " Removes the value associated with the given key from the slab, returning"] # [doc = " it."] # [doc = ""] # [doc = " If the slab does not contain a value for that key, `None` is returned"] # [doc = " instead."] # [doc = ""] # [doc = " If the value associated with the given key is currently being"] # [doc = " accessed by another thread, this method will block the current thread"] # [doc = " until the item is no longer accessed. If this is not desired, use"] # [doc = " [`remove`] instead."] # [doc = ""] # [doc = " **Note**: This method blocks the calling thread by spinning until the"] # [doc = " currently outstanding references are released. Spinning for long periods"] # [doc = " of time can result in high CPU time and power consumption. Therefore,"] # [doc = " `take` should only be called when other references to the slot are"] # [doc = " expected to be dropped soon (e.g., when all accesses are relatively"] # [doc = " short)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " let slab = sharded_slab::Slab::new();"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Remove the item from the slab, returning it."] # [doc = " assert_eq!(slab.take(key), Some(\"hello world\"));"] # [doc = ""] # [doc = " // Now, the slot is empty."] # [doc = " assert!(!slab.contains(key));"] # [doc = " ```"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " let slab = Arc::new(sharded_slab::Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " let slab2 = slab.clone();"] # [doc = " let thread2 = std::thread::spawn(move || {"] # [doc = "     // Depending on when this thread begins executing, the item may"] # [doc = "     // or may not have already been removed..."] # [doc = "     if let Some(item) = slab2.get(key) {"] # [doc = "         assert_eq!(item, \"hello world\");"] # [doc = "     }"] # [doc = " });"] # [doc = ""] # [doc = " // The item will only be removed when the other thread finishes"] # [doc = " // accessing it."] # [doc = " assert_eq!(slab.take(key), Some(\"hello world\"));"] # [doc = ""] # [doc = " thread2.join().unwrap();"] # [doc = " assert!(!slab.contains(key));"] # [doc = " ```"] # [doc = " [`remove`]: Slab::remove"] pub fn take (& self , idx : usize) -> Option < T > { let tid = C :: unpack_tid (idx) ; test_println ! ("rm {:?}" , tid) ; let shard = self . shards . get (tid . as_usize ()) ? ; if tid . is_current () { shard . take_local (idx) } else { shard . take_remote (idx) } } # [doc = " Return a reference to the value associated with the given key."] # [doc = ""] # [doc = " If the slab does not contain a value for the given key, or if the"] # [doc = " maximum number of concurrent references to the slot has been reached,"] # [doc = " `None` is returned instead."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " let slab = sharded_slab::Slab::new();"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " assert_eq!(slab.get(key).unwrap(), \"hello world\");"] # [doc = " assert!(slab.get(12345).is_none());"] # [doc = " ```"] pub fn get (& self , key : usize) -> Option < Entry < '_ , T , C > > { let tid = C :: unpack_tid (key) ; test_println ! ("get {:?}; current={:?}" , tid , Tid ::< C >:: current ()) ; let shard = self . shards . get (tid . as_usize ()) ? ; shard . with_slot (key , | slot | { let inner = slot . get (C :: unpack_gen (key)) ? ; let value = ptr :: NonNull :: from (slot . value () . as_ref () . unwrap ()) ; Some (Entry { inner , value , shard , key , }) }) } # [doc = " Return an owned reference to the value at the given index."] # [doc = ""] # [doc = " If the slab does not contain a value for the given key, `None` is"] # [doc = " returned instead."] # [doc = ""] # [doc = " Unlike [`get`], which borrows the slab, this method _clones_ the [`Arc`]"] # [doc = " around the slab. This means that the returned [`OwnedEntry`] can be held"] # [doc = " for an arbitrary lifetime. However,  this method requires that the slab"] # [doc = " itself be wrapped in an `Arc`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let value = slab.clone().get_owned(key).unwrap();"] # [doc = ""] # [doc = " // Now, the original `Arc` clone of the slab may be dropped, but the"] # [doc = " // returned `OwnedEntry` can still access the value."] # [doc = " assert_eq!(value, \"hello world\");"] # [doc = " ```"] # [doc = ""] # [doc = " Unlike [`Entry`], an `OwnedEntry` may be stored in a struct which must live"] # [doc = " for the `'static` lifetime:"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use sharded_slab::OwnedEntry;"] # [doc = " use std::sync::Arc;"] # [doc = ""] # [doc = " pub struct MyStruct {"] # [doc = "     entry: OwnedEntry<&'static str>,"] # [doc = "     // ... other fields ..."] # [doc = " }"] # [doc = ""] # [doc = " // Suppose this is some arbitrary function which requires a value that"] # [doc = " // lives for the 'static lifetime..."] # [doc = " fn function_requiring_static<T: 'static>(t: &T) {"] # [doc = "     // ... do something extremely important and interesting ..."] # [doc = " }"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let entry = slab.clone().get_owned(key).unwrap();"] # [doc = " let my_struct = MyStruct {"] # [doc = "     entry,"] # [doc = "     // ..."] # [doc = " };"] # [doc = ""] # [doc = " // We can use `my_struct` anywhere where it is required to have the"] # [doc = " // `'static` lifetime:"] # [doc = " function_requiring_static(&my_struct);"] # [doc = " ```"] # [doc = ""] # [doc = " [`OwnedEntry`]s may be sent between threads:"] # [doc = ""] # [doc = " ```"] # [doc = " # use sharded_slab::Slab;"] # [doc = " use std::{thread, sync::Arc};"] # [doc = ""] # [doc = " let slab: Arc<Slab<&'static str>> = Arc::new(Slab::new());"] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = ""] # [doc = " // Look up the created key, returning an `OwnedEntry`."] # [doc = " let value = slab.clone().get_owned(key).unwrap();"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "     assert_eq!(value, \"hello world\");"] # [doc = "     // ..."] # [doc = " }).join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " [`get`]: Slab::get"] # [doc = " [`Arc`]: std::sync::Arc"] pub fn get_owned (self : Arc < Self > , key : usize) -> Option < OwnedEntry < T , C > > { let tid = C :: unpack_tid (key) ; test_println ! ("get_owned {:?}; current={:?}" , tid , Tid ::< C >:: current ()) ; let shard = self . shards . get (tid . as_usize ()) ? ; shard . with_slot (key , | slot | { let inner = slot . get (C :: unpack_gen (key)) ? ; let value = ptr :: NonNull :: from (slot . value () . as_ref () . unwrap ()) ; Some (OwnedEntry { inner , value , slab : self . clone () , key , }) }) } # [doc = " Returns `true` if the slab contains a value for the given key."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " let slab = sharded_slab::Slab::new();"] # [doc = ""] # [doc = " let key = slab.insert(\"hello world\").unwrap();"] # [doc = " assert!(slab.contains(key));"] # [doc = ""] # [doc = " slab.take(key).unwrap();"] # [doc = " assert!(!slab.contains(key));"] # [doc = " ```"] pub fn contains (& self , key : usize) -> bool { self . get (key) . is_some () } # [doc = " Returns an iterator over all the items in the slab."] # [doc = ""] # [doc = " Because this iterator exclusively borrows the slab (i.e. it holds an"] # [doc = " `&mut Slab<T>`), elements will not be added or removed while the"] # [doc = " iteration is in progress."] pub fn unique_iter (& mut self) -> iter :: UniqueIter < '_ , T , C > { let mut shards = self . shards . iter_mut () ; let (pages , slots) = match shards . next () { Some (shard) => { let mut pages = shard . iter () ; let slots = pages . next () . and_then (page :: Shared :: iter) ; (pages , slots) } None => ([] . iter () , None) , } ; iter :: UniqueIter { shards , pages , slots , } } }
}